300	            runningApp: RobotAppStatus? = nil,
301	            automaticConnectionAllowed: Bool = true,
302	            supportsRename: Bool = true,
303	            client: any RobotAPIClient = PreviewRobotClient()
304	        ) -> RobotSession {
305	            let session = RobotSession { _ in client }
306	            session.supportsRename = supportsRename
307	            // Claimed without connecting: the capability flags a screen asks about
308	            // (`canConfigureWiFi`, `canManageApps`, `canLinkHuggingFace`) are all
309	            // "does this client speak that protocol", and a nil client answers no
310	            // to every one of them.
311	            session.client = client
312	            session.phase = phase
313	            session.lastStatus = status
314	            session.link = link ?? address.map(RobotSession.Link.lan) ?? .none
315	            session.robotError = error
316	            session.powerTransition = powerTransition
317	            session.compatibilityWarning = compatibilityWarning
318	            session.currentMove = currentMove
319	            session.isStoppingMove = isStoppingMove
320	            session.runningApp = runningApp
321	            session.automaticConnectionAllowed = automaticConnectionAllowed
322	            return session
323	        }
324	    }
325	
326	    /// A radio that is switched on and never hears anything. `FakeBLETransport` replays the
327	    /// GATT exchange to drive a protocol test; this one exists so a `BLELink` can be built
328	    /// at all, and every state a screen renders is set on the link directly.
329	    ///
330	    /// The two write lengths are the pair `OnboardingJoinStep` prints, at the values a
331	    /// current iPhone reports.
332	    public final class PreviewBLETransport: BLETransport {
333	        public let availability: BLEAvailability
334	        public let discovered: [BLEPeripheralSnapshot]
335	        public let maximumWriteLength: Int
336	        public let attributeWriteLength: Int
337	
338	        public init(
339	            availability: BLEAvailability = .ready,
340	            discovered: [BLEPeripheralSnapshot] = [],
341	            maximumWriteLength: Int = 182,
342	            attributeWriteLength: Int = 512
343	        ) {
344	            self.availability = availability
345	            self.discovered = discovered
346	            self.maximumWriteLength = maximumWriteLength
347	            self.attributeWriteLength = attributeWriteLength
348	        }
349	
350	        public func startScan() throws {}
351	
352	        public func stopScan() {}
353	
354	        public func connect(_: UUID) async throws {}
355	
356	        public func disconnect() {}
357	
358	        public func setNotify(_: Bool, for _: BLECharacteristicID) async throws {}
359	
360	        public func write(_: Data, to _: BLECharacteristicID) async throws {
361	            throw BLETransportError.notConnected
362	        }
363	
364	        public func read(_ characteristic: BLECharacteristicID) async throws -> Data {
365	            throw BLETransportError.characteristicMissing(characteristic)
366	        }
367	
368	        /// Finished rather than open: `BLELink.observe()` iterates this on `init`, and a
369	        /// stream that never ends would leave a task alive behind every preview card.
370	        public func notifications() -> AsyncStream<Data> {
371	            AsyncStream { $0.finish() }
372	        }
373	
374	        public func events() -> AsyncStream<BLETransportEvent> {
375	            AsyncStream { $0.finish() }
376	        }
377	    }
