5	/// Freeing the robot's disk, and the one way to uninstall every app at once.
6	///
7	/// Both routes live at the app root under `--wireless-version`, so this whole
8	/// section is absent on a Lite robot and over the relay — `canPerformMaintenance`
9	/// answers for both.
10	struct MaintenanceCard: View {
11	    let session: RobotSession
12	
13	    @State private var model: MaintenanceModel
14	
15	    /// `@MainActor` because `MaintenanceModel` is: a defaulted argument whose
16	    /// value is main-actor-isolated compiles in the SwiftPM targets and not in
17	    /// the `Apps/` ones, where it is evaluated nonisolated.
18	    @MainActor
19	    init(session: RobotSession, model: MaintenanceModel? = nil) {
20	        self.session = session
21	        _model = State(initialValue: model ?? MaintenanceModel())
22	    }
23	
24	    var body: some View {
25	        Section {
26	            action(
27	                .clearHuggingFaceCache,
28	                description: .reachy("Model weights the robot has downloaded. An app fetches what it needs again."),
29	                button: .reachy("Clear Hugging Face cache"),
30	                systemImage: "arrow.down.circle.dotted"
31	            )
32	            action(
33	                .resetApps,
34	                description: resetDescription,
35	                button: .reachy("Uninstall all apps"),
36	                systemImage: "trash"
37	            )
38	            if let lastError = model.lastError {
39	                Text(lastError)
40	                    .font(.caption)
41	                    .foregroundStyle(.red)
42	            }
43	        } header: {
44	            Text(.reachy("Maintenance"))
45	        } footer: {
46	            Text(.reachy("Neither can be undone from here."))
47	        }
48	        .confirmationDialog(
49	            confirmation.title,
50	            isPresented: isConfirming,
51	            titleVisibility: .visible
52	        ) {
53	            if let pending = model.confirming {
54	                Button(confirmation.confirm, role: .destructive) {
55	                    Task { await model.perform(pending, session: session) }
56	                }
57	            }
58	        } message: {
59	            Text(confirmation.message)
60	        }
61	    }
62	
63	    /// The robot's own dashboard puts the sentence above the button, and it is
64	    /// the right way round for something irreversible: the reader meets what it
65	    /// does before they meet the thing that does it.
66	    private func action(
67	        _ action: MaintenanceModel.Action,
68	        description: LocalizedStringResource,
69	        button: LocalizedStringResource,
70	        systemImage: String
71	    ) -> some View {
72	        VStack(alignment: .leading, spacing: Space.sm) {
73	            Text(description)
74	                .font(.caption)
75	                .foregroundStyle(.secondary)
76	            HStack {
77	                Button(role: .destructive) {
78	                    model.confirming = action
79	                } label: {
80	                    Label(button, systemImage: systemImage)
81	                }
82	                .buttonStyle(.borderless)
83	                .disabled(model.isBusy || isBlocked(action))
84	                Spacer()
85	                trailing(for: action)
86	            }
87	        }
88	    }
89	
90	    @ViewBuilder
91	    private func trailing(for action: MaintenanceModel.Action) -> some View {
92	        if model.running == action {
93	            ProgressView().controlSize(.small)
94	        } else if model.finished == action {
95	            Image(systemName: "checkmark.circle.fill")
96	                .foregroundStyle(.green)
97	                .accessibilityLabel(.reachy("Done"))
98	        }
99	    }
100	
101	    /// Names the app in the way, rather than leaving a greyed-out button with no
102	    /// explanation — the reader would have no idea what to do about it.
103	    private var resetDescription: LocalizedStringResource {
104	        if let blocking = model.blockingApp(session) {
105	            .reachy("Stop \(blocking.title) first — uninstalling deletes the environment it is running in.")
106	        } else {
107	            .reachy("Every installed app, and the Python environment they share.")
108	        }
109	    }
110	
111	    private func isBlocked(_ action: MaintenanceModel.Action) -> Bool {
112	        action == .resetApps && model.blockingApp(session) != nil
113	    }
114	
115	    private var isConfirming: Binding<Bool> {
116	        Binding(
117	            get: { model.confirming != nil },
118	            set: { presented in
119	                if !presented {
120	                    model.confirming = nil
121	                }
122	            }
123	        )
124	    }
125	
126	    /// A type rather than a tuple, and its three keys deliberately do not echo
127	    /// the button labels: the catalogue derives a Swift symbol per key, and two
128	    /// keys differing only in punctuation — `Uninstall all apps` against
129	    /// `Uninstall all apps?` — collide as a hard `xcstringstool` build error.
130	    private struct Confirmation {
131	        let title: LocalizedStringResource
132	        let message: LocalizedStringResource
133	        let confirm: LocalizedStringResource
134	    }
135	
136	    private var confirmation: Confirmation {
137	        switch model.confirming {
138	        case .resetApps:
139	            Confirmation(
140	                title: .reachy("Remove every app?"),
141	                message: .reachy("Every app is deleted from the robot, along with the Python environment they share."),
142	                confirm: .reachy("Uninstall all")
143	            )
144	        // `.clearHuggingFaceCache` and nil share this arm: the dialog is only on
145	        // screen while `confirming` is set, and the property has to answer anyway.
146	        // Spelled out rather than `default`, so a third action is a compile error
147	        // here instead of silently inheriting this one's wording.
148	        case .clearHuggingFaceCache, .none:
149	            Confirmation(
150	                title: .reachy("Clear cached models?"),
151	                // swiftlint:disable:next line_length
152	                message: .reachy(
153	                    "Downloaded model weights are deleted. The robot downloads them again when an app needs them."
154	                ),
155	                confirm: .reachy("Clear cache")
156	            )
157	        }
158	    }
159	}
